const navToggle = document.querySelector('[data-menu-toggle]');const navLinks = document.querySelector('[data-nav-links]');if (navToggle && navLinks) {navToggle.addEventListener('click', () => navLinks.classList.toggle('open'));navLinks.querySelectorAll('a').forEach(a => a.addEventListener('click', () => navLinks.classList.remove('open')));}document.querySelectorAll('.faq-question').forEach(btn => {btn.addEventListener('click', () => btn.closest('.faq-item').classList.toggle('open'));});function reservationUrl(vehicleClass = '') {const q = vehicleClass ? `?class=${encodeURIComponent(vehicleClass)}` : '';return `/reserve${q}`;}document.querySelectorAll('[data-request-class]').forEach(btn => {btn.addEventListener('click', () => {window.location.href = reservationUrl(btn.dataset.requestClass || '');});});document.querySelectorAll('.reserve-class').forEach(card => {card.addEventListener('click', () => {document.querySelectorAll('.reserve-class').forEach(c => c.classList.remove('selected'));card.classList.add('selected');const select = document.querySelector('select[name="vehicleClass"]');if (select) select.value = card.dataset.vehicleClass || '';});});const params = new URLSearchParams(location.search);const requestedClass = params.get('class');if (requestedClass) {const select = document.querySelector('select[name="vehicleClass"]');if (select) {const match = [...select.options].find(o => o.value.toLowerCase() === requestedClass.toLowerCase());if (match) select.value = match.value;}document.querySelectorAll('.reserve-class').forEach(card => {if ((card.dataset.vehicleClass || '').toLowerCase() === requestedClass.toLowerCase()) card.classList.add('selected');});}const modal = document.querySelector('[data-modal]');const closeModal = () => modal?.classList.remove('open');document.querySelectorAll('[data-close-modal]').forEach(btn => btn.addEventListener('click', closeModal));modal?.addEventListener('click', e => { if (e.target === modal) closeModal(); });function handleReservation(form) {const data = new FormData(form);const pick = data.get('pickupDate');const drop = data.get('dropoffDate');if (pick && drop && new Date(drop) < new Date(pick)) {alert('Drop off date must be after the pick up date.');return;}const summary = document.querySelector('[data-reservation-summary]');if (summary) {const vehicleClass = data.get('vehicleClass') || 'your selected class';const location = data.get('pickupLocation') || data.get('deliveryLocation') || 'your requested location';summary.textContent = `Your ${vehicleClass} request for ${location} is ready to send. A Priority One will confirm availability and your rate directly.`;}modal?.classList.add('open');const mailBtn = document.querySelector('[data-email-request]');if (mailBtn) {const lines = ['A Priority One rental request','',`Pick up date: ${data.get('pickupDate') || ''}`,`Drop off date: ${data.get('dropoffDate') || ''}`,`Pick up location: ${data.get('pickupLocation') || data.get('deliveryLocation') || ''}`,`Drop off location: ${data.get('dropoffLocation') || ''}`,`Vehicle class: ${data.get('vehicleClass') || ''}`,`Name: ${data.get('name') || ''}`,`Phone: ${data.get('phone') || ''}`,`Email: ${data.get('email') || ''}`,`Notes: ${data.get('notes') || ''}`,];mailBtn.href = `mailto:info@apriorityone.com?subject=${encodeURIComponent('Rental Request')}&body=${encodeURIComponent(lines.join('\n'))}`;}}document.querySelectorAll('[data-reservation-form]').forEach(form => {form.addEventListener('submit', e => {e.preventDefault();handleReservation(form);});});